async () => {
      try {
        const result = await run();
        if (result) {
          job.snapshotId = result;
        }
        job.status = job.stopRequested ? 'cancelled' : 'completed';
        job.phase =
          job.status === 'cancelled' ? 'Snapshot stopped' : 'Completed';
      } catch (error) {
        if (
          job.operation === 'create' &&
          job.stopRequested &&
          error instanceof Error &&
          error.name === 'RawMigrationCancelledError'
        ) {
          job.status = 'cancelled';
          job.phase = 'Snapshot stopped';
          return;
        }
        job.status = 'failed';
        job.phase = 'Failed';

        if (error instanceof Error) {
          job.error = error.message;
          job.errorStack = error.stack;
        } else {
          job.error = 'Raw migration failed.';
          job.errorStack = String(error);
        }
      }
    }

